SELECT id, preparation_id, section_key, input_revision, content_kind, content_text, facts_json, run_id, created_at, confirmed_at
FROM application_preparation_content WHERE preparation_id = #{preparationId} AND section_key = #{sectionKey}
ORDER BY id DESC LIMIT 1

SELECT id, preparation_id, section_key, input_revision, expected_version_id, request_key, run_status,
       input_json, output_json, applied, started_at, finished_at
FROM application_preparation_draft_run WHERE preparation_id = #{preparationId} AND request_key = #{requestKey}
